insert into T_GSQ_SCHEDULE_RESULT (ID, SCHEDULE_DATE, TQ_BATCH_NO, BATCH_NO, ORDER_NO, STEEL_TYPE, STEEL_RING_CODE, RANK, MACHINE_ID, UNIT_CONSUME, STOCK_QTY, SUPPLY_TIME, MID_PLAN_QTY, MID_PRODUCE_ORDER, MID_SYS_ANALYSIS, MID_HAND_ANALYSIS, NIGHT_PLAN_QTY, NIGHT_PRODUCE_ORDER, NIGHT_SYS_ANALYSIS, NIGHT_HAND_ANALYSIS, DAY_PLAN_QTY, DAY_PRODUCE_ORDER, DAY_SYS_ANALYSIS, DAY_HAND_ANALYSIS,CX_CLASS1_PLAN, CX_CLASS2_PLAN, CX_CLASS3_PLAN, CX_CLASS4_PLAN, CX_CLASS5_PLAN, IS_RELEASE, MARK_CLOSE_OUT_TIP, PRODUCTION_STATUS, REMARK, DEL_FLAG, CREATE_BY, CREATE_TIME,PUBLISH_SUCCESS_COUNT, NEWEST_PUBLISH_TIME) select SEQ_GSQ_SCHEDULE.NEXTVAL AS ID, x.* from (
select #{schedule.scheduleDate}, #{schedule.tqBatchNo,jdbcType=VARCHAR}, #{schedule.batchNo}, #{schedule.orderNo}, #{schedule.steelType,jdbcType=VARCHAR}, #{schedule.steelRingCode,jdbcType=VARCHAR}, #{schedule.rank,jdbcType=VARCHAR}, #{schedule.machineId,jdbcType=VARCHAR}, #{schedule.unitConsume,jdbcType=DOUBLE}, #{schedule.stockQty,jdbcType=DOUBLE}, #{schedule.supplyTime,jdbcType=DOUBLE}, #{schedule.midPlanQty,jdbcType=DOUBLE}, #{schedule.midProduceOrder,jdbcType=DOUBLE}, #{schedule.midSysAnalysis,jdbcType=VARCHAR}, #{schedule.midHandAnalysis,jdbcType=VARCHAR}, #{schedule.nightPlanQty,jdbcType=DOUBLE}, #{schedule.nightProduceOrder,jdbcType=DOUBLE}, #{schedule.nightSysAnalysis,jdbcType=VARCHAR}, #{schedule.nightHandAnalysis,jdbcType=VARCHAR}, #{schedule.dayPlanQty,jdbcType=DOUBLE}, #{schedule.dayProduceOrder,jdbcType=DOUBLE}, #{schedule.daySysAnalysis,jdbcType=VARCHAR}, #{schedule.dayHandAnalysis,jdbcType=VARCHAR},#{schedule.cxClass1Plan,jdbcType=DOUBLE},#{schedule.cxClass2Plan,jdbcType=DOUBLE},#{schedule.cxClass3Plan,jdbcType=DOUBLE},#{schedule.cxClass4Plan,jdbcType=DOUBLE},#{schedule.cxClass5Plan,jdbcType=DOUBLE}, #{schedule.isRelease}, #{schedule.markCloseOutTip}, #{schedule.productionStatus}, #{schedule.remark,jdbcType=VARCHAR}, #{schedule.delFlag}, #{schedule.createBy}, #{schedule.createTime},nvl(#{schedule.publishSuccessCount,jdbcType=DOUBLE},0),#{schedule.newestPublishTime,jdbcType=DATE} from dual
) x

insert into T_GSQ_ASSIST_SCHEDULE (ID, SCHEDULE_DATE, TQ_BATCH_NO, BATCH_NO, ORDER_NO, STEEL_TYPE, STEEL_RING_CODE, RANK, MACHINE_ID, UNIT_CONSUME, STOCK_QTY, SUPPLY_TIME, MID_PLAN_QTY, MID_PRODUCE_ORDER, MID_SYS_ANALYSIS, MID_HAND_ANALYSIS, NIGHT_PLAN_QTY, NIGHT_PRODUCE_ORDER, NIGHT_SYS_ANALYSIS, NIGHT_HAND_ANALYSIS, DAY_PLAN_QTY, DAY_PRODUCE_ORDER, DAY_SYS_ANALYSIS, DAY_HAND_ANALYSIS,CX_CLASS1_PLAN, CX_CLASS2_PLAN, CX_CLASS3_PLAN, CX_CLASS4_PLAN, CX_CLASS5_PLAN, IS_RELEASE, MARK_CLOSE_OUT_TIP, PRODUCTION_STATUS, REMARK, DEL_FLAG, CREATE_BY, CREATE_TIME) select SEQ_GSQ_SCHEDULE.NEXTVAL AS ID, x.* from (
select #{schedule.scheduleDate}, #{schedule.tqBatchNo}, #{schedule.batchNo}, #{schedule.orderNo}, #{schedule.steelType,jdbcType=VARCHAR}, #{schedule.steelRingCode,jdbcType=VARCHAR}, #{schedule.rank,jdbcType=VARCHAR}, #{schedule.machineId,jdbcType=VARCHAR}, #{schedule.unitConsume,jdbcType=DOUBLE}, #{schedule.stockQty,jdbcType=DOUBLE}, #{schedule.supplyTime,jdbcType=DOUBLE}, #{schedule.midPlanQty,jdbcType=DOUBLE}, #{schedule.midProduceOrder,jdbcType=DOUBLE}, #{schedule.midSysAnalysis,jdbcType=VARCHAR}, #{schedule.midHandAnalysis,jdbcType=VARCHAR}, #{schedule.nightPlanQty,jdbcType=DOUBLE}, #{schedule.nightProduceOrder,jdbcType=DOUBLE}, #{schedule.nightSysAnalysis,jdbcType=VARCHAR}, #{schedule.nightHandAnalysis,jdbcType=VARCHAR}, #{schedule.dayPlanQty,jdbcType=DOUBLE}, #{schedule.dayProduceOrder,jdbcType=DOUBLE}, #{schedule.daySysAnalysis,jdbcType=VARCHAR}, #{schedule.dayHandAnalysis,jdbcType=VARCHAR},#{schedule.cxClass1Plan,jdbcType=DOUBLE},#{schedule.cxClass2Plan,jdbcType=DOUBLE},#{schedule.cxClass3Plan,jdbcType=DOUBLE},#{schedule.cxClass4Plan,jdbcType=DOUBLE},#{schedule.cxClass5Plan,jdbcType=DOUBLE}, #{schedule.isRelease}, #{schedule.markCloseOutTip}, #{schedule.productionStatus}, #{schedule.remark,jdbcType=VARCHAR}, #{schedule.delFlag}, #{schedule.createBy}, #{schedule.createTime} from dual
) x

mapper.update:
merge into t_gsq_schedule_result a USING (
select #{schedule.scheduleDate} schedule_date, #{schedule.tqBatchNo,jdbcType=VARCHAR} tq_batch_no, #{schedule.batchNo,jdbcType=VARCHAR} batch_no, #{schedule.orderNo,jdbcType=VARCHAR} order_no, #{schedule.steelType,jdbcType=VARCHAR} steel_type, #{schedule.steelRingCode,jdbcType=VARCHAR} steel_ring_code, #{schedule.rank,jdbcType=VARCHAR} rank, #{schedule.machineId,jdbcType=VARCHAR} machine_id, #{schedule.unitConsume,jdbcType=DOUBLE} unit_consume, #{schedule.stockQty,jdbcType=DOUBLE} stock_qty, #{schedule.supplyTime,jdbcType=DOUBLE} supply_time, #{schedule.midPlanQty,jdbcType=DOUBLE} mid_plan_qty, #{schedule.midProduceOrder,jdbcType=DOUBLE} mid_produce_order, #{schedule.midSysAnalysis,jdbcType=VARCHAR} mid_sys_analysis, #{schedule.midHandAnalysis,jdbcType=VARCHAR} mid_hand_analysis, #{schedule.nightPlanQty,jdbcType=DOUBLE} night_plan_qty, #{schedule.nightProduceOrder,jdbcType=DOUBLE} night_produce_order, #{schedule.nightSysAnalysis,jdbcType=VARCHAR} night_sys_analysis, #{schedule.nightHandAnalysis,jdbcType=VARCHAR} night_hand_analysis, #{schedule.dayPlanQty,jdbcType=DOUBLE} day_plan_qty, #{schedule.dayProduceOrder,jdbcType=DOUBLE} day_produce_order, #{schedule.daySysAnalysis,jdbcType=VARCHAR} day_sys_analysis, #{schedule.dayHandAnalysis,jdbcType=VARCHAR} day_hand_analysis, #{schedule.isRelease,jdbcType=VARCHAR} is_release, #{schedule.markCloseOutTip,jdbcType=VARCHAR} mark_close_out_tip, #{schedule.productionStatus,jdbcType=VARCHAR} production_status, #{schedule.remark,jdbcType=VARCHAR} remark, #{schedule.delFlag,jdbcType=VARCHAR} del_flag, #{schedule.createBy,jdbcType=VARCHAR} create_by, #{schedule.createTime} create_time, #{schedule.dataSource,jdbcType=VARCHAR} data_source, #{schedule.cxClass1Plan,jdbcType=DOUBLE} cx_class1_plan, #{schedule.cxClass2Plan,jdbcType=DOUBLE} cx_class2_plan, #{schedule.cxClass3Plan,jdbcType=DOUBLE} cx_class3_plan, #{schedule.cxClass4Plan,jdbcType=DOUBLE} cx_class4_plan, #{schedule.cxClass5Plan,jdbcType=DOUBLE} cx_class5_plan from dual
) b ON (a.schedule_date = b.schedule_date AND a.steel_ring_code = b.steel_ring_code AND a.machine_id = b.machine_id AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.mid_plan_qty = b.mid_plan_qty, a.mid_hand_analysis = b.mid_hand_analysis, a.night_plan_qty = b.night_plan_qty, a.night_hand_analysis = b.night_hand_analysis, a.day_plan_qty = b.day_plan_qty, a.day_hand_analysis = b.day_hand_analysis, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark, a.data_source = b.data_source, a.cx_class1_plan = b.cx_class1_plan, a.cx_class2_plan = b.cx_class2_plan, a.cx_class3_plan = b.cx_class3_plan, a.cx_class4_plan = b.cx_class4_plan, a.cx_class5_plan = b.cx_class5_plan WHEN NOT MATCHED THEN INSERT (a.ID,a.SCHEDULE_DATE,a.TQ_BATCH_NO,a.BATCH_NO,a.ORDER_NO,a.STEEL_TYPE,a.STEEL_RING_CODE,a.RANK,a.MACHINE_ID,a.UNIT_CONSUME,a.STOCK_QTY,a.SUPPLY_TIME,a.MID_PLAN_QTY,a.MID_PRODUCE_ORDER,a.MID_SYS_ANALYSIS,a.MID_HAND_ANALYSIS,a.NIGHT_PLAN_QTY,a.NIGHT_PRODUCE_ORDER,a.NIGHT_SYS_ANALYSIS,a.NIGHT_HAND_ANALYSIS,a.DAY_PLAN_QTY,a.DAY_PRODUCE_ORDER,a.DAY_SYS_ANALYSIS,a.DAY_HAND_ANALYSIS,a.IS_RELEASE,a.MARK_CLOSE_OUT_TIP,a.PRODUCTION_STATUS,a.REMARK,a.DEL_FLAG,a.CREATE_BY,a.CREATE_TIME,a.data_source) values (SEQ_GSQ_SCHEDULE.NEXTVAL,b.SCHEDULE_DATE,b.TQ_BATCH_NO,b.BATCH_NO,b.ORDER_NO,b.STEEL_TYPE,b.STEEL_RING_CODE,b.RANK,b.MACHINE_ID,b.UNIT_CONSUME,b.STOCK_QTY,b.SUPPLY_TIME,b.MID_PLAN_QTY,b.MID_PRODUCE_ORDER,b.MID_SYS_ANALYSIS,b.MID_HAND_ANALYSIS,b.NIGHT_PLAN_QTY,b.NIGHT_PRODUCE_ORDER,b.NIGHT_SYS_ANALYSIS,b.NIGHT_HAND_ANALYSIS,b.DAY_PLAN_QTY,b.DAY_PRODUCE_ORDER,b.DAY_SYS_ANALYSIS,b.DAY_HAND_ANALYSIS,b.IS_RELEASE,b.MARK_CLOSE_OUT_TIP,b.PRODUCTION_STATUS,b.REMARK,b.DEL_FLAG,b.CREATE_BY,b.CREATE_TIME,b.data_source)
